import Foundation
import SuflyorDomain
import SuflyorTestSupport

@testable import SuflyorImporters

/// Files generated by tools/ios/make_import_fixtures.py, copied into the test bundle as the `Fixtures` folder.
enum Fixture {
    struct Missing: Error { let name: String }

    static func data(_ name: String) throws -> Data {
        guard let base = Bundle.module.resourceURL else { throw Missing(name: name) }
        let url = base.appendingPathComponent("Fixtures").appendingPathComponent(name)
        guard let data = try? Data(contentsOf: url) else { throw Missing(name: name) }
        return data
    }
}

/// The importer under test, over the test core (Markdown handling there is simplistic: only dispatch is checked).
func makeImporter() -> DocumentImporter { DocumentImporter(core: SimpleScriptCore()) }

/// The `ImportError` a block throws, nil when it doesn't throw.
func errorOf<T>(_ body: () throws -> T) -> ImportError? {
    do {
        _ = try body()
        return nil
    } catch let error as ImportError {
        return error
    } catch {
        return nil
    }
}

/// `text` sliced by UTF-16 offsets, as `TextRange` counts them.
func slice(_ text: String, _ range: TextRange) -> String {
    String(decoding: Array(text.utf16)[range.start..<range.end], as: UTF16.self)
}

func texts(_ doc: ImportedDocument) -> [String] { doc.paragraphs.map(\.text) }

func emphasized(_ p: ScriptParagraph) -> [String] { p.emphasis.map { slice(p.text, $0) } }
